    static inline auto eefk(const std::array<float, 3> &x) noexcept -> Eigen::Isometry3f
    {
        std::array<float, 0> v;
        std::array<float, 12> y;

           y[3] = cos(x[2]);
   y[4] = sin(x[2]);
   y[6] = 0. - y[4];
   // variable duplicates: 1
   y[7] = y[3];
   // dependent variables without operations
   y[0] = x[0];
   y[1] = x[1];
   y[2] = 0.;
   y[5] = 0.;
   y[8] = 0.;
   y[9] = 0.;
   y[10] = 0.;
   y[11] = 1.;


        return to_isometry(y.data());
    }
